import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"PRD-036 — Collectible cards: one shareable card per real thing","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-036.md","filePath":"prd/PRD-036.md"}'),o={name:"prd/PRD-036.md"};function n(i,e,l,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="prd-036-—-collectible-cards-one-shareable-card-per-real-thing" tabindex="-1">PRD-036 — Collectible cards: one shareable card per real thing <a class="header-anchor" href="#prd-036-—-collectible-cards-one-shareable-card-per-real-thing" aria-label="Permalink to &quot;PRD-036 — Collectible cards: one shareable card per real thing&quot;">​</a></h1><p><em>Status: Shipped (2026-09-12, #547 · retro-documented) · Architecture: TA.md §components &quot;Collectible cards&quot; + §pipelines Pipeline 13 + §contracts CardSpec</em></p><blockquote><p><strong>One-liner.</strong> Every entity with a detail panel — missions, fleet hardware, landing sites, planets, moons, small bodies — carries a baseball-card-style collectible the user can open in-app and share as a link (with a real social unfurl) or as an image file.</p></blockquote><blockquote><p>Why this is a PRD · Orrery&#39;s content is deep but private — a user who loves the Apollo 11 panel has no artifact to put in a group chat, a classroom slide, or a feed. Cards turn every entity into a shareable, collectible object with the app&#39;s editorial voice baked in: the share IS the acquisition surface (the unfurled card is the ad; the tap-through lands on the live panel). It changes how Orrery spreads, not just how it looks.</p></blockquote><h2 id="_1-·-what-shipped" tabindex="-1">1 · What shipped <a class="header-anchor" href="#_1-·-what-shipped" aria-label="Permalink to &quot;1 · What shipped&quot;">​</a></h2><ul><li><strong>407 canonical cards</strong> across 7 kinds: 125 missions · 227 fleet · 9 moon/mars sites · 8 planets · 16 moons · 22 small bodies. Every wired detail panel (missions, fleet, moon/mars/venus/earth surface panels, earth objects, planets, satellites, small bodies) shows a quiet &quot;Collector card&quot; CTA.</li><li><strong>One card per real thing.</strong> Entities that exist on multiple surfaces share ONE card: 47 fleet entries that ARE missions, 45 of 54 moon+mars sites (+ all 3 Venus sites), and 30 of 31 earth objects alias to their canonical mission/fleet card — identical alias logic in panels, generator, and share stubs.</li><li><strong>Design: template, never generation.</strong> One pure HTML/CSS template (01 &quot;cinematic&quot;, locked after a 7-round design consultation) renders every card; a restyle is a template edit that applies to all 407 instantly. Nothing is hand-made or AI-generated per entity. The card hero IS the entity&#39;s app hero (override-blessed <code>gallery[0]</code>) — a bad card hero means a bad hero, fixed at the override (no-panorama rule, 2026-09-12).</li><li><strong>Two share actions.</strong> <em>Share link</em> shares the prerendered <code>/c/&lt;kind&gt;/&lt;id&gt;</code> stub — crawlers see the Open Graph card image, humans get redirected into the live panel. <em>Share card</em> hands the generated 1080×1440 JPEG to the native share sheet (download fallback).</li><li><strong>In-app cards are translated</strong> (14-locale chrome, RTL-safe values); the generated JPEG corpus + stubs are en-US by design (one corpus).</li></ul><h2 id="_2-·-users" tabindex="-1">2 · Users <a class="header-anchor" href="#_2-·-users" aria-label="Permalink to &quot;2 · Users&quot;">​</a></h2><p>Space enthusiast (collect + share), curious learner (the unfurl is the hook), educator/journalist (drop-in visual with honest sourcing), the operator (organic acquisition).</p><h2 id="_3-·-non-goals" tabindex="-1">3 · Non-goals <a class="header-anchor" href="#_3-·-non-goals" aria-label="Permalink to &quot;3 · Non-goals&quot;">​</a></h2><ul><li><strong>No per-entity art generation</strong> — explicitly rejected (&quot;thousand Higgsfield calls makes no sense&quot;). Design consultation was AI-assisted; production is markup.</li><li><strong>No stars/exoplanet cards</strong> — deliberately skipped until card-grade imagery exists (10/62 stars, 0 exoplanets today).</li><li><strong>No localized JPEG corpora</strong> — 14× render cost for share files whose text is secondary to the image; revisit on demand.</li><li><strong>No card-collection meta-game</strong> (albums, owned/unowned state) — cards are share artifacts, not progression mechanics. Revisit only with a concrete engagement thesis.</li></ul><h2 id="_4-·-measurement" tabindex="-1">4 · Measurement <a class="header-anchor" href="#_4-·-measurement" aria-label="Permalink to &quot;4 · Measurement&quot;">​</a></h2><p>Umami events on card opens + shares (<code>card-open</code> / share actions ride the existing panel analytics); stub-page hits in the deploy logs are the unfurl-to-visit funnel.</p><h2 id="_5-·-pointers" tabindex="-1">5 · Pointers <a class="header-anchor" href="#_5-·-pointers" aria-label="Permalink to &quot;5 · Pointers&quot;">​</a></h2><p>Implementation contract + invariants: <code>docs/adr/TA.md</code> (§components &quot;Collectible cards&quot;, §pipelines Pipeline 13, §contracts CardSpec) and <code>src/lib/cards/README.md</code>. Imagery follow-ups: #550. Epic: #547.</p>',14)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
